import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        System.out.println(aboveAverage(arr));
    }

    static int aboveAverage(int[] scores) {
        long total = 0;
        for (int s : scores) {
            total += s;
        }
        double avg = total / (double) scores.length;
        int count = 0;
        for (int s : scores) {
            if (s > avg) {
                count++;
            }
        }
        return count;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] slots = new int[n];
        for (int i = 0; i < n; i++) slots[i] = sc.nextInt();
        ArrayList<Integer> out = new ArrayList<>();
        levelOrder(buildLevelOrder(slots), out);
        so.println(joinList(out));
    }

    static TNode buildLevelOrder(int[] slots) {
        if (slots.length == 0 || slots[0] == -1) return null;
        TNode root = new TNode(slots[0]);
        ArrayDeque<TNode> queue = new ArrayDeque<>();
        queue.add(root);
        int i = 1;
        while (!queue.isEmpty() && i < slots.length) {
            TNode parent = queue.poll();
            if (i < slots.length) {
                if (slots[i] != -1) {
                    parent.left = new TNode(slots[i]);
                    queue.add(parent.left);
                }
                i++;
            }
            if (i < slots.length) {
                if (slots[i] != -1) {
                    parent.right = new TNode(slots[i]);
                    queue.add(parent.right);
                }
                i++;
            }
        }
        return root;
    }

    static String joinList(ArrayList<Integer> out) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < out.size(); i++) {
            if (i > 0) sb.append(' ');
            sb.append(out.get(i));
        }
        return sb.toString();
    }

    static final class TNode {
        int val;
        TNode left;
        TNode right;
        TNode(int val) { this.val = val; }
    }

    static void levelOrder(TNode root, ArrayList<Integer> out) {
        if (root == null) return;
        ArrayDeque<TNode> queue = new ArrayDeque<>();
        queue.add(root);
        while (!queue.isEmpty()) {
            TNode node = queue.poll();
            out.add(node.val);
            if (node.left != null) queue.add(node.left);
            if (node.right != null) queue.add(node.right);
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] vals = new int[n];
        for (int i = 0; i < n; i++) {
            vals[i] = sc.nextInt();
        }

        int value = sc.nextInt();
        System.out.println(printDll(insertFront(buildDll(vals), value)));
    }

    static DNode insertFront(DNode head, int value) {
        DNode node = new DNode(value);
        node.next = head;
        if (head != null) {
            head.prev = node;
        }
        return node;
    }

    static DNode buildDll(int[] vals) {
        DNode head = null;
        DNode tail = null;
        for (int v : vals) {
            DNode node = new DNode(v);
            if (head == null) {
                head = node;
            } else {
                tail.next = node;
                node.prev = tail;
            }
            tail = node;
        }
        return head;
    }

    static DNode tailOf(DNode head) {
        DNode cur = head;
        while (cur.next != null) {
            cur = cur.next;
        }
        return cur;
    }

    static String printDll(DNode head) {
        StringBuilder sb = new StringBuilder();
        for (DNode cur = head; cur != null; cur = cur.next) {
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(cur.data);
        }
        return sb.toString();
    }

    static class DNode {
        int data;
        DNode prev;
        DNode next;

        DNode(int data) {
            this.data = data;
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        String t = sc.next();
        System.out.println(isAnagram(s, t) ? 1 : 0);
    }

    static boolean isAnagram(String s, String t) {
        if (s.length() != t.length()) {
            return false;
        }
        int[] freq = new int[26];
        for (int i = 0; i < s.length(); i++) {
            freq[s.charAt(i) - 'a']++;
            freq[t.charAt(i) - 'a']--;
        }
        for (int i = 0; i < 26; i++) {
            if (freq[i] != 0) {
                return false;
            }
        }
        return true;
    }
}

