public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] deadlines = new int[n];
        for (int i = 0; i < n; i++) deadlines[i] = sc.nextInt();
        so.println(maxJobs(deadlines));
    }

    static int maxJobs(int[] deadlines) {
        int[] sorted = deadlines.clone();
        Arrays.sort(sorted);
        int time = 0, done = 0;
        for (int d : sorted) {
            if (time < d) {
                time++;
                done++;
            }
        }
        return done;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        String a = sc.next();
        String b = sc.next();
        so.println(editDistance(a, b));
    }

    static int editDistance(String a, String b) {
        int n = a.length(), m = b.length();
        int[][] dp = new int[n + 1][m + 1];
        for (int i = 0; i <= n; i++) dp[i][0] = i;
        for (int j = 0; j <= m; j++) dp[0][j] = j;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (a.charAt(i - 1) == b.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1];
                } else {
                    int ins = dp[i][j - 1] + 1;
                    int del = dp[i - 1][j] + 1;
                    int rep = dp[i - 1][j - 1] + 1;
                    dp[i][j] = Math.min(ins, Math.min(del, rep));
                }
            }
        }
        return dp[n][m];
    }
}

