public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt(), e = sc.nextInt();
        ArrayList<ArrayList<Integer>> g = new ArrayList<>();
        for (int i = 0; i < v; i++) g.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt(), w = sc.nextInt();
            g.get(u).add(w);
            g.get(w).add(u);
        }
        int start = sc.nextInt();
        ArrayList<Integer> out = new ArrayList<>();
        bfs(g, start, out);
        System.out.println(joinList(out));
    }

    static String joinList(ArrayList<Integer> a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.size(); i++) {
            if (i > 0) sb.append(' ');
            sb.append(a.get(i));
        }
        return sb.toString();
    }

    static void bfs(ArrayList<ArrayList<Integer>> g, int start, ArrayList<Integer> out) {
        boolean[] visited = new boolean[g.size()];
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        visited[start] = true;
        queue.add(start);
        while (!queue.isEmpty()) {
            int u = queue.poll();
            out.add(u);
            for (int w : g.get(u)) {
                if (!visited[w]) {
                    visited[w] = true;
                    queue.add(w);
                }
            }
        }
    }
}

