public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        System.out.println(isBalanced(s));
    }

    static int isBalanced(String s) {
        ArrayDeque<Character> st = new ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(' || c == '[' || c == '{') {
                st.push(c);
            } else {
                if (st.isEmpty()) return 0;
                char open = st.pop();
                if (c == ')' && open != '(') return 0;
                if (c == ']' && open != '[') return 0;
                if (c == '}' && open != '{') return 0;
            }
        }
        return st.isEmpty() ? 1 : 0;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        java.io.PrintStream so = System.out;

        int n = sc.nextInt();
        so.println(balancedSet(n));
    }

    static String balancedSet(int n) {
        StringBuilder sb = new StringBuilder();
        gen(sb, new char[2 * n], 0, 0, 0, n);
        return sb.toString();
    }

    static void gen(StringBuilder sb, char[] buf, int pos, int open, int close, int n) {
        if (pos == 2 * n) {
            if (sb.length() > 0) {
                sb.append('\n');
            }
            sb.append(buf);
            return;
        }
        if (open < n) {
            buf[pos] = '(';
            gen(sb, buf, pos + 1, open + 1, close, n);
        }
        if (close < open) {
            buf[pos] = ')';
            gen(sb, buf, pos + 1, open, close + 1, n);
        }
    }
}

