public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] start = new int[n];
        for (int i = 0; i < n; i++) start[i] = sc.nextInt();
        int[] end = new int[n];
        for (int i = 0; i < n; i++) end[i] = sc.nextInt();
        so.println(minArrows(start, end));
    }

    static int minArrows(int[] start, int[] end) {
        int n = start.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> end[a] - end[b]);
        int arrows = 0;
        long shot = Long.MIN_VALUE;
        for (int i : idx) {
            if (start[i] > shot) {
                arrows++;
                shot = end[i];
            }
        }
        return arrows;
    }
}

