public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int backs = sc.nextInt();
        int[] visits = new int[n];
        for (int i = 0; i < n; i++) visits[i] = sc.nextInt();
        System.out.println(currentPage(visits, backs));
    }

    static int currentPage(int[] visits, int backs) {
        ArrayDeque<Integer> st = new ArrayDeque<>();
        for (int v : visits) st.push(v);
        for (int i = 0; i < backs && !st.isEmpty(); i++) st.pop();
        return st.isEmpty() ? -1 : st.peek();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        bubbleSort(arr);
        System.out.println(join(arr));
    }

    static void bubbleSort(int[] arr) {
        int n = arr.length;
        for (int i = 0; i < n - 1; i++) {
            boolean swapped = false;
            for (int j = 0; j + 1 < n - i; j++) {
                if (arr[j] > arr[j + 1]) {
                    int t = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = t;
                    swapped = true;
                }
            }
            if (!swapped) {
                break;
            }
        }
    }

    static String join(int[] a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(a[i]);
        }
        return sb.toString();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        java.io.PrintStream so = System.out;
        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        long[] counts = swapComparison(arr);
        so.println(counts[0] + " " + counts[1]);
    }

    static long[] swapComparison(int[] arr) {
        int n = arr.length;
        int[] sel = arr.clone();
        long selSwaps = 0;
        for (int i = 0; i < n - 1; i++) {
            int min = i;
            for (int j = i + 1; j < n; j++) {
                if (sel[j] < sel[min]) {
                    min = j;
                }
            }
            if (min != i) {
                int t = sel[i];
                sel[i] = sel[min];
                sel[min] = t;
                selSwaps++;
            }
        }
        int[] bub = arr.clone();
        long bubSwaps = 0;
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j + 1 < n - i; j++) {
                if (bub[j] > bub[j + 1]) {
                    int t = bub[j];
                    bub[j] = bub[j + 1];
                    bub[j + 1] = t;
                    bubSwaps++;
                }
            }
        }
        return new long[] { selSwaps, bubSwaps };
    }
}

