public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt(), e = sc.nextInt();
        ArrayList<ArrayList<Integer>> g = new ArrayList<>();
        for (int i = 0; i < v; i++) g.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt(), w = sc.nextInt();
            g.get(u).add(w);
        }
        so.println(hasCycle(g));
    }

    static int hasCycle(ArrayList<ArrayList<Integer>> g) {
        int[] color = new int[g.size()];
        for (int s = 0; s < g.size(); s++) {
            if (color[s] == 0 && dfsCycle(g, s, color)) return 1;
        }
        return 0;
    }

    static boolean dfsCycle(ArrayList<ArrayList<Integer>> g, int u, int[] color) {
        color[u] = 1;
        for (int w : g.get(u)) {
            if (color[w] == 1) return true;
            if (color[w] == 0 && dfsCycle(g, w, color)) return true;
        }
        color[u] = 2;
        return false;
    }
}

