public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] vals = new int[n];
        for (int i = 0; i < n; i++) {
            vals[i] = sc.nextInt();
        }

        System.out.println(dllLength(buildDll(vals)));
    }

    static int dllLength(DNode head) {
        int size = 0;
        for (DNode cur = head; cur != null; cur = cur.next) {
            size++;
        }
        return size;
    }

    static DNode buildDll(int[] vals) {
        DNode head = null;
        DNode tail = null;
        for (int v : vals) {
            DNode node = new DNode(v);
            if (head == null) {
                head = node;
            } else {
                tail.next = node;
                node.prev = tail;
            }
            tail = node;
        }
        return head;
    }

    static DNode tailOf(DNode head) {
        DNode cur = head;
        while (cur.next != null) {
            cur = cur.next;
        }
        return cur;
    }

    static String printDll(DNode head) {
        StringBuilder sb = new StringBuilder();
        for (DNode cur = head; cur != null; cur = cur.next) {
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(cur.data);
        }
        return sb.toString();
    }

    static class DNode {
        int data;
        DNode prev;
        DNode next;

        DNode(int data) {
            this.data = data;
        }
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] slots = new int[n];
        for (int i = 0; i < n; i++) slots[i] = sc.nextInt();
        int v = sc.nextInt();
        TNode root = buildLevelOrder(slots);
        ArrayList<Integer> out = new ArrayList<>();
        inorder(bstInsert(root, v), out);
        System.out.println(joinList(out));
    }

    static TNode buildLevelOrder(int[] slots) {
        if (slots.length == 0 || slots[0] == -1) return null;
        TNode root = new TNode(slots[0]);
        ArrayDeque<TNode> queue = new ArrayDeque<>();
        queue.add(root);
        int i = 1;
        while (!queue.isEmpty() && i < slots.length) {
            TNode parent = queue.poll();
            if (i < slots.length) {
                if (slots[i] != -1) {
                    parent.left = new TNode(slots[i]);
                    queue.add(parent.left);
                }
                i++;
            }
            if (i < slots.length) {
                if (slots[i] != -1) {
                    parent.right = new TNode(slots[i]);
                    queue.add(parent.right);
                }
                i++;
            }
        }
        return root;
    }

    static String joinList(ArrayList<Integer> out) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < out.size(); i++) {
            if (i > 0) sb.append(' ');
            sb.append(out.get(i));
        }
        return sb.toString();
    }

    static final class TNode {
        int val;
        TNode left;
        TNode right;
        TNode(int val) { this.val = val; }
    }

    static void inorder(TNode root, ArrayList<Integer> out) {
        if (root == null) return;
        inorder(root.left, out);
        out.add(root.val);
        inorder(root.right, out);
    }

    static TNode bstInsert(TNode root, int v) {
        if (root == null) return new TNode(v);
        if (v < root.val) root.left = bstInsert(root.left, v);
        else root.right = bstInsert(root.right, v);
        return root;
    }
}

