public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int capacity = sc.nextInt();
        int m = sc.nextInt();
        initQueue(capacity);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < m; i++) {
            String op = sc.next();
            if (op.equals("e")) {
                int x = sc.nextInt();
                sb.append(enqueue(x));
            } else {
                sb.append(dequeue());
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }

    static int[] store;
    static int head, tail, count, cap;

    static void initQueue(int capacity) {
        store = new int[capacity];
        cap = capacity;
        head = 0;
        tail = 0;
        count = 0;
    }

    static int enqueue(int v) {
        if (count == cap) return 0;
        store[tail] = v;
        tail = (tail + 1) % cap;
        count++;
        return 1;
    }

    static int dequeue() {
        if (count == 0) return -1;
        int v = store[head];
        head = (head + 1) % cap;
        count--;
        return v;
    }
}

