        so.println(collatzSteps(n));
    }

    static long collatzSteps(long n) {
        long steps = 0;
        while (n != 1) {
            if (n % 2 == 0) {
                n /= 2;
            } else {
                n = 3 * n + 1;
            }
            steps++;
        }
        return steps;
    }
}

