        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt(), e = sc.nextInt();
        ArrayList<ArrayList<Integer>> g = new ArrayList<>();
        for (int i = 0; i < v; i++) g.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt(), w = sc.nextInt();
            g.get(u).add(w);
            g.get(w).add(u);
        }
        so.println(joinList(componentSizes(g)));
    }

    static String joinList(ArrayList<Integer> a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.size(); i++) {
            if (i > 0) sb.append(' ');
            sb.append(a.get(i));
        }
        return sb.toString();
    }

    static ArrayList<Integer> componentSizes(ArrayList<ArrayList<Integer>> g) {
        boolean[] visited = new boolean[g.size()];
        ArrayList<Integer> sizes = new ArrayList<>();
        for (int s = 0; s < g.size(); s++) {
            if (!visited[s]) sizes.add(mark(g, s, visited));
        }
        Collections.sort(sizes);
        return sizes;
    }

    static int mark(ArrayList<ArrayList<Integer>> g, int s, boolean[] visited) {
        int count = 0;
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        visited[s] = true;
        queue.add(s);
        while (!queue.isEmpty()) {
            int u = queue.poll();
            count++;
            for (int w : g.get(u)) {
                if (!visited[w]) {
                    visited[w] = true;
                    queue.add(w);
                }
            }
        }
        return count;
    }
}

