    static long bubbleSwaps(int[] arr) {
        int[] a = arr.clone();
        long swaps = 0;
        int n = a.length;
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j + 1 < n - i; j++) {
                if (a[j] > a[j + 1]) {
                    int t = a[j];
                    a[j] = a[j + 1];
                    a[j + 1] = t;
                    swaps++;
                }
            }
        }
        return swaps;
    }
