        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        System.out.println(insertionShifts(arr));
    }

    static long insertionShifts(int[] arr) {
        int[] a = arr.clone();
        long shifts = 0;
        for (int i = 1; i < a.length; i++) {
            int key = a[i];
            int j = i - 1;
            while (j >= 0 && a[j] > key) {
                a[j + 1] = a[j];
                j--;
                shifts++;
            }
            a[j + 1] = key;
        }
        return shifts;
    }
}

