        Scanner sc = new Scanner(System.in);
        java.io.PrintStream so = System.out;

        int n = sc.nextInt();
        so.println(mergeWrites(n));
    }

    static long mergeWrites(int n) {
        long total = 0;
        int[] stack = new int[128];
        int top = 0;
        stack[top++] = n;
        while (top > 0) {
            int size = stack[--top];
            if (size <= 1) {
                continue;
            }
            total += size;
            int half = size / 2;
            stack[top++] = size - half;
            stack[top++] = half;
        }
        return total;
    }
}

