        ArrayList<ArrayList<Integer>> g = new ArrayList<>();
        for (int i = 0; i < v; i++) g.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt(), w = sc.nextInt();
            g.get(u).add(w);
            g.get(w).add(u);
        }
        int s = sc.nextInt();
        so.println(joinArr(bfsDistances(g, s)));
    }

    static String joinArr(int[] a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.length; i++) {
            if (i > 0) sb.append(' ');
            sb.append(a[i]);
        }
        return sb.toString();
    }

    static int[] bfsDistances(ArrayList<ArrayList<Integer>> g, int s) {
        int[] dist = new int[g.size()];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        dist[s] = 0;
        queue.add(s);
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int w : g.get(u)) {
                if (dist[w] == -1) {
                    dist[w] = dist[u] + 1;
                    queue.add(w);
                }
            }
        }
        return dist;
    }
}

