        boolean[] visited = new boolean[g.size()];
        explore(g, start, visited, out);
    }

    static void explore(ArrayList<ArrayList<Integer>> g, int u, boolean[] visited, ArrayList<Integer> out) {
        visited[u] = true;
        out.add(u);
        for (int w : g.get(u)) {
            if (!visited[w]) explore(g, w, visited, out);
        }
    }
}

