        Node head = buildList(vals);
        if (pos >= 0) {
            Node tail = head;
            while (tail.next != null) {
                tail = tail.next;
            }
            Node join = head;
            for (int i = 0; i < pos; i++) {
                join = join.next;
            }
            tail.next = join;
        }
