    }

    static long permutationCount(String s) {
        int[] freq = new int[26];
        for (int i = 0; i < s.length(); i++) {
            freq[s.charAt(i) - 'a']++;
        }
        long result = 1;
        for (int len = 2; len <= s.length(); len++) {
            result *= len;
        }
        for (int c = 0; c < 26; c++) {
