public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] bins = new int[n];
        for (int i = 0; i < n; i++) bins[i] = sc.nextInt();
        flagSort(bins);
        so.println(joinArr(bins));
    }

    static String joinArr(int[] a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.length; i++) {
            if (i > 0) sb.append(' ');
            sb.append(a[i]);
        }
        return sb.toString();
    }

    static void flagSort(int[] bins) {
        int low = 0, mid = 0, high = bins.length - 1;
        while (mid <= high) {
            if (bins[mid] == 0) {
                int tmp = bins[low];
                bins[low] = bins[mid];
                bins[mid] = tmp;
                low++;
                mid++;
            } else if (bins[mid] == 2) {
                int tmp = bins[mid];
                bins[mid] = bins[high];
                bins[high] = tmp;
                high--;
            } else {
                mid++;
            }
        }
    }
}

