        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }
        int target = sc.nextInt();

        System.out.println(findRoll(arr, target));
    }

    static int findRoll(int[] rolls, int target) {
        int lo = 0;
        int hi = rolls.length - 1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (rolls[mid] == target) {
                return mid;
            }
            if (rolls[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return -1;
    }
}

