        long e = sc.nextLong();
        long m = sc.nextLong();
        so.println(fastPower(b, e, m));
    }

    static long fastPower(long b, long e, long m) {
        if (e == 0) {
            return 1 % m;
        }
        long half = fastPower(b, e / 2, m);
        long result = (half * half) % m;
        if (e % 2 == 1) {
            result = (result * (b % m)) % m;
        }
        return result;
    }
}

