        }
        int s = sc.nextInt(), t = sc.nextInt();
        so.println(hopDistance(g, s, t));
    }

    static int hopDistance(ArrayList<ArrayList<Integer>> g, int s, int t) {
        int[] dist = new int[g.size()];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        dist[s] = 0;
        queue.add(s);
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int w : g.get(u)) {
                if (dist[w] == -1) {
                    dist[w] = dist[u] + 1;
                    queue.add(w);
                }
            }
        }
        return dist[t];
    }
}

