        for (int i = 0; i < n; i++) {
            vals[i] = sc.nextInt();
        }

        int pos = sc.nextInt();
        Node head = buildList(vals);
        if (pos >= 0) {
            Node tail = head;
            while (tail.next != null) {
                tail = tail.next;
            }
            Node join = head;
            for (int i = 0; i < pos; i++) {
                join = join.next;
            }
            tail.next = join;
        }
        System.out.println(cycleStart(head));
    }

    static int cycleStart(Node head) {
        Node slow = head;
        Node fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {
                Node start = head;
                while (start != slow) {
                    start = start.next;
                    slow = slow.next;
                }
                return slow.data;
            }
        }
        return -1;
    }

    static Node buildList(int[] vals) {
        Node head = null;
        Node tail = null;
        for (int v : vals) {
            Node node = new Node(v);
            if (head == null) {
                head = node;
            } else {
                tail.next = node;
            }
            tail = node;
        }
        return head;
    }

    static String printList(Node head) {
        StringBuilder sb = new StringBuilder();
        for (Node cur = head; cur != null; cur = cur.next) {
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(cur.data);
        }
        return sb.toString();
    }

    static class Node {
        int data;
        Node next;

        Node(int data) {
            this.data = data;
        }
    }
}

