        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt(), e = sc.nextInt();
        ArrayList<ArrayList<Integer>> g = new ArrayList<>();
        for (int i = 0; i < v; i++) g.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt(), w = sc.nextInt();
            g.get(u).add(w);
            g.get(w).add(u);
        }
        so.println(componentCount(g));
    }

    static int componentCount(ArrayList<ArrayList<Integer>> g) {
        boolean[] visited = new boolean[g.size()];
        int count = 0;
        for (int s = 0; s < g.size(); s++) {
            if (!visited[s]) {
                count++;
                markComponent(g, s, visited);
            }
        }
        return count;
    }

    static void markComponent(ArrayList<ArrayList<Integer>> g, int s, boolean[] visited) {
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        visited[s] = true;
        queue.add(s);
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int w : g.get(u)) {
                if (!visited[w]) {
                    visited[w] = true;
                    queue.add(w);
                }
            }
        }
    }
}

