public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextInt();
        buildMinHeap(a);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.length; i++) {
            if (i > 0) sb.append(' ');
            sb.append(a[i]);
        }
        so.println(sb.toString());
    }

    static void buildMinHeap(int[] a) {
        int n = a.length;
        for (int i = n / 2 - 1; i >= 0; i--) siftDown(a, i, n);
    }

    static void siftDown(int[] a, int i, int n) {
        while (true) {
            int smallest = i;
            int l = 2 * i + 1;
            int r = 2 * i + 2;
            if (l < n && a[l] < a[smallest]) smallest = l;
            if (r < n && a[r] < a[smallest]) smallest = r;
            if (smallest == i) return;
            int tmp = a[i];
            a[i] = a[smallest];
            a[smallest] = tmp;
            i = smallest;
        }
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] slots = new int[n];
        for (int i = 0; i < n; i++) slots[i] = sc.nextInt();
        System.out.println(height(buildLevelOrder(slots)));
    }

    static TNode buildLevelOrder(int[] slots) {
        if (slots.length == 0 || slots[0] == -1) return null;
        TNode root = new TNode(slots[0]);
        ArrayDeque<TNode> queue = new ArrayDeque<>();
        queue.add(root);
        int i = 1;
        while (!queue.isEmpty() && i < slots.length) {
            TNode parent = queue.poll();
            if (i < slots.length) {
                if (slots[i] != -1) {
                    parent.left = new TNode(slots[i]);
                    queue.add(parent.left);
                }
                i++;
            }
            if (i < slots.length) {
                if (slots[i] != -1) {
                    parent.right = new TNode(slots[i]);
                    queue.add(parent.right);
                }
                i++;
            }
        }
        return root;
    }

    static String joinList(ArrayList<Integer> out) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < out.size(); i++) {
            if (i > 0) sb.append(' ');
            sb.append(out.get(i));
        }
        return sb.toString();
    }

    static final class TNode {
        int val;
        TNode left;
        TNode right;
        TNode(int val) { this.val = val; }
    }

    static int height(TNode root) {
        if (root == null) return 0;
        return 1 + Math.max(height(root.left), height(root.right));
    }
}

