        Scanner sc = new Scanner(System.in);
        java.io.PrintStream so = System.out;
        long n = sc.nextLong();
        so.println(intSqrt(n));
    }

    static long intSqrt(long n) {
        long lo = 0;
        long hi = 2000000000;
        while (lo < hi) {
            long mid = (lo + hi + 1) / 2;
            if (mid <= n / mid) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        return lo;
    }
}

