public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt(), e = sc.nextInt();
        ArrayList<ArrayList<Integer>> g = new ArrayList<>();
        for (int i = 0; i < v; i++) g.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt(), w = sc.nextInt();
            g.get(u).add(w);
            g.get(w).add(u);
        }
        so.println(isTree(g));
    }

    static int isTree(ArrayList<ArrayList<Integer>> g) {
        int edges = 0;
        for (ArrayList<Integer> nbrs : g) edges += nbrs.size();
        edges /= 2;
        if (edges != g.size() - 1) return 0;
        boolean[] visited = new boolean[g.size()];
        explore(g, 0, visited);
        for (boolean b : visited) {
            if (!b) return 0;
        }
        return 1;
    }

    static void explore(ArrayList<ArrayList<Integer>> g, int u, boolean[] visited) {
        visited[u] = true;
        for (int w : g.get(u)) {
            if (!visited[w]) explore(g, w, visited);
        }
    }
}

