    }

    static int dllSum(DNode head) {
        int total = 0;
        for (DNode cur = head; cur != null; cur = cur.next) {
            total += cur.data;
        }
        return total;
    }

    static DNode buildDll(int[] vals) {
        DNode head = null;
        DNode tail = null;
        for (int v : vals) {
            DNode node = new DNode(v);
            if (head == null) {
                head = node;
            } else {
                tail.next = node;
                node.prev = tail;
            }
            tail = node;
        }
        return head;
    }

    static DNode tailOf(DNode head) {
        DNode cur = head;
        while (cur.next != null) {
            cur = cur.next;
        }
        return cur;
    }

    static String printDll(DNode head) {
        StringBuilder sb = new StringBuilder();
        for (DNode cur = head; cur != null; cur = cur.next) {
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(cur.data);
        }
        return sb.toString();
    }

    static class DNode {
        int data;
        DNode prev;
        DNode next;

        DNode(int data) {
            this.data = data;
        }
    }
}

