        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        System.out.println(partitionLast(arr));
    }

    static int partitionLast(int[] arr) {
        int n = arr.length;
        int pivot = arr[n - 1];
        int i = 0;
        for (int j = 0; j < n - 1; j++) {
            if (arr[j] <= pivot) {
                int t = arr[i];
                arr[i] = arr[j];
                arr[j] = t;
                i++;
            }
        }
        int t = arr[i];
        arr[i] = arr[n - 1];
        arr[n - 1] = t;
        return i;
    }
}

