        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        mergeSortArr(arr);
        System.out.println(join(arr));
    }

    static void mergeSortArr(int[] arr) {
        msort(arr, new int[arr.length], 0, arr.length - 1);
    }

    static void msort(int[] a, int[] tmp, int lo, int hi) {
        if (lo >= hi) {
            return;
        }
        int mid = (lo + hi) / 2;
        msort(a, tmp, lo, mid);
        msort(a, tmp, mid + 1, hi);
        int i = lo;
        int j = mid + 1;
        int k = lo;
        while (i <= mid && j <= hi) {
            if (a[i] <= a[j]) {
                tmp[k++] = a[i++];
            } else {
                tmp[k++] = a[j++];
            }
        }
        while (i <= mid) {
            tmp[k++] = a[i++];
        }
        while (j <= hi) {
            tmp[k++] = a[j++];
        }
        for (int x = lo; x <= hi; x++) {
            a[x] = tmp[x];
        }
    }

    static String join(int[] a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(a[i]);
        }
        return sb.toString();
    }
}

