    }

    static char mostFrequent(String s) {
        HashMap<Character, Integer> freq = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            freq.merge(c, 1, Integer::sum);
        }
        char best = 'z';
        int bestCount = 0;
        for (char c = 'a'; c <= 'z'; c++) {
            int cnt = freq.getOrDefault(c, 0);
            if (cnt > bestCount) {
                bestCount = cnt;
                best = c;
            }
        }
        return best;
    }
}

