    static DNode insertBack(DNode head, int value) {
        DNode node = new DNode(value);
        if (head == null) {
            return node;
        }
        DNode tail = tailOf(head);
        tail.next = node;
        node.prev = tail;
        return head;
    }

    static DNode buildDll(int[] vals) {
        DNode head = null;
        DNode tail = null;
        for (int v : vals) {
            DNode node = new DNode(v);
            if (head == null) {
                head = node;
            } else {
                tail.next = node;
                node.prev = tail;
            }
            tail = node;
        }
        return head;
    }

    static DNode tailOf(DNode head) {
        DNode cur = head;
        while (cur.next != null) {
            cur = cur.next;
        }
        return cur;
    }

    static String printDll(DNode head) {
        StringBuilder sb = new StringBuilder();
        for (DNode cur = head; cur != null; cur = cur.next) {
            if (sb.length() > 0) {
                sb.append(' ');
