        String s = sc.next();
        System.out.println(isPalindrome(s));
    }

    static int isPalindrome(String s) {
        return check(s, 0, s.length() - 1);
    }

    static int check(String s, int lo, int hi) {
        if (lo >= hi) {
            return 1;
        }
        if (s.charAt(lo) != s.charAt(hi)) {
            return 0;
        }
        return check(s, lo + 1, hi - 1);
    }
}

