        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }
        long[] out = productExceptSelf(arr);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(out[i]);
        }
        System.out.println(sb);
    }

    static long[] productExceptSelf(int[] arr) {
        int n = arr.length;
        long[] pre = new long[n];
        long[] suf = new long[n];
        pre[0] = 1;
        for (int i = 1; i < n; i++) {
            pre[i] = pre[i - 1] * arr[i - 1];
        }
        suf[n - 1] = 1;
        for (int i = n - 2; i >= 0; i--) {
            suf[i] = suf[i + 1] * arr[i + 1];
        }
        long[] out = new long[n];
        for (int i = 0; i < n; i++) {
            out[i] = pre[i] * suf[i];
        }
        return out;
    }
}

