public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        java.io.PrintStream so = System.out;

        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        so.println(quickDepth(arr));
    }

    static int quickDepth(int[] arr) {
        return depth(arr, 0, arr.length - 1);
    }

    static int depth(int[] a, int lo, int hi) {
        if (lo >= hi) {
            return 0;
        }
        int p = qpartition(a, lo, hi);
        int left = depth(a, lo, p - 1);
        int right = depth(a, p + 1, hi);
        return 1 + Math.max(left, right);
    }

    static int qpartition(int[] a, int lo, int hi) {
        int pivot = a[hi];
        int i = lo;
        for (int j = lo; j < hi; j++) {
            if (a[j] <= pivot) {
                int t = a[i];
                a[i] = a[j];
                a[j] = t;
                i++;
            }
        }
        int t = a[i];
        a[i] = a[hi];
        a[hi] = t;
        return i;
    }
}

