            arr[i] = sc.nextInt();
        }

        sortByScoreDesc(arr);
        System.out.println(join(arr));
    }

    static void sortByScoreDesc(int[] scores) {
        int n = scores.length;
        for (int i = 0; i < n - 1; i++) {
            int max = i;
            for (int j = i + 1; j < n; j++) {
                if (scores[j] > scores[max]) {
                    max = j;
                }
            }
            if (max != i) {
                int t = scores[i];
                scores[i] = scores[max];
                scores[max] = t;
            }
        }
    }

    static String join(int[] a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(a[i]);
        }
        return sb.toString();
    }
}

