public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        java.io.PrintStream so = System.out;

        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        so.println(reversePairs(arr));
    }

    static long reversePairs(int[] arr) {
        return revCount(arr.clone(), new int[arr.length], 0, arr.length - 1);
    }

    static long revCount(int[] a, int[] tmp, int lo, int hi) {
        if (lo >= hi) {
            return 0;
        }
        int mid = (lo + hi) / 2;
        long count = revCount(a, tmp, lo, mid) + revCount(a, tmp, mid + 1, hi);
        int i = lo;
        for (int j = mid + 1; j <= hi; j++) {
            while (i <= mid && (long) a[i] <= 2L * a[j]) {
                i++;
            }
            count += mid - i + 1;
        }
        int x = lo;
        int y = mid + 1;
        int k = lo;
        while (x <= mid && y <= hi) {
            if (a[x] <= a[y]) {
                tmp[k++] = a[x++];
            } else {
                tmp[k++] = a[y++];
            }
        }
        while (x <= mid) {
            tmp[k++] = a[x++];
        }
        while (y <= hi) {
            tmp[k++] = a[y++];
        }
        for (int t = lo; t <= hi; t++) {
            a[t] = tmp[t];
        }
        return count;
    }
}

