    }

    static String compress(String s) {
        StringBuilder sb = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            int run = 0;
            while (i < s.length() && s.charAt(i) == c) {
                run++;
                i++;
            }
            sb.append(c);
            if (run > 1) {
                sb.append(run);
            }
        }
        return sb.toString();
    }
}

