public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        java.io.PrintStream so = System.out;

        int n = sc.nextInt();
        int[] vals = new int[n];
        for (int i = 0; i < n; i++) {
            vals[i] = sc.nextInt();
        }

        int value = sc.nextInt();
        so.println(printDll(dllInsertSorted(buildDll(vals), value)));
    }

    static DNode dllInsertSorted(DNode head, int value) {
        DNode node = new DNode(value);
        if (value < head.data) {
            node.next = head;
            head.prev = node;
            return node;
        }
        DNode cur = head;
        while (cur.next != null && cur.next.data <= value) {
            cur = cur.next;
        }
        node.next = cur.next;
        if (cur.next != null) {
            cur.next.prev = node;
        }
        cur.next = node;
        node.prev = cur;
        return head;
    }

    static DNode buildDll(int[] vals) {
        DNode head = null;
        DNode tail = null;
        for (int v : vals) {
            DNode node = new DNode(v);
            if (head == null) {
                head = node;
            } else {
                tail.next = node;
                node.prev = tail;
            }
            tail = node;
        }
        return head;
    }

    static DNode tailOf(DNode head) {
        DNode cur = head;
        while (cur.next != null) {
            cur = cur.next;
        }
        return cur;
    }

    static String printDll(DNode head) {
        StringBuilder sb = new StringBuilder();
        for (DNode cur = head; cur != null; cur = cur.next) {
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(cur.data);
        }
        return sb.toString();
    }

    static class DNode {
        int data;
        DNode prev;
        DNode next;

        DNode(int data) {
            this.data = data;
        }
    }
}

