        }
        so.println(stableOrder(values, ids));
    }

    static int stableOrder(int[] values, int[] ids) {
        for (int i = 1; i < values.length; i++) {
            if (values[i] < values[i - 1]) {
                return 0;
            }
            if (values[i] == values[i - 1] && ids[i] < ids[i - 1]) {
                return 0;
            }
        }
        return 1;
    }
}

