        for (int x : arr) {
            if (x < v) {
                res[idx++] = x;
            }
        }
        for (int x : arr) {
            if (x == v) {
                res[idx++] = x;
            }
        }
        for (int x : arr) {
            if (x > v) {
                res[idx++] = x;
            }
        }
        return res;
    }

