    static long countSubarrays(int[] a, int k) {
        HashMap<Long, Integer> prefixCounts = new HashMap<>();
        prefixCounts.put(0L, 1);
        long sum = 0;
        long count = 0;
        for (int v : a) {
            sum += v;
            count += prefixCounts.getOrDefault(sum - k, 0);
            prefixCounts.merge(sum, 1, Integer::sum);
        }
        return count;
    }
}

