        Node fast = head;
        steps = 0;
        while (steps < k) {
            fast = fast.next;
            steps++;
        }
        Node second = head;
        while (fast != null) {
            fast = fast.next;
            second = second.next;
        }
        int tmp = first.data;
        first.data = second.data;
        second.data = tmp;
        return head;
    }

