public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt(), e = sc.nextInt();
        ArrayList<ArrayList<Integer>> g = new ArrayList<>();
        for (int i = 0; i < v; i++) g.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt(), w = sc.nextInt();
            g.get(u).add(w);
            g.get(w).add(u);
        }
        so.println(isBipartite(g));
    }

    static int isBipartite(ArrayList<ArrayList<Integer>> g) {
        int v = g.size();
        int[] color = new int[v];
        for (int s = 0; s < v; s++) {
            if (color[s] != 0) continue;
            ArrayDeque<Integer> queue = new ArrayDeque<>();
            color[s] = 1;
            queue.add(s);
            while (!queue.isEmpty()) {
                int u = queue.poll();
                for (int w : g.get(u)) {
                    if (color[w] == 0) {
                        color[w] = -color[u];
                        queue.add(w);
                    } else if (color[w] == color[u]) {
                        return 0;
                    }
                }
            }
        }
        return 1;
    }
}

