    static int[] insertionAfterK(int[] arr, int k) {
        int[] a = arr.clone();
        for (int i = 1; i <= k - 1; i++) {
            int key = a[i];
            int j = i - 1;
            while (j >= 0 && a[j] > key) {
                a[j + 1] = a[j];
                j--;
            }
            a[j + 1] = key;
        }
        return a;
    }

