        int val;
        TNode left;
        TNode right;
        TNode(int val) { this.val = val; }
    }

    static boolean bstSearch(TNode root, int v) {
        while (root != null) {
            if (v == root.val) return true;
            root = (v < root.val) ? root.left : root.right;
        }
        return false;
    }
}

