        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        System.out.println(tribonacci(n));
    }

    static long tribonacci(int n) {
        if (n == 0) return 0;
        if (n <= 2) return 1;
        long a = 0, b = 1, c = 1;
        for (int i = 3; i <= n; i++) {
            long d = a + b + c;
            a = b;
            b = c;
            c = d;
        }
        return c;
    }
}

