public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt(), e = sc.nextInt();
        ArrayList<ArrayList<Integer>> g = new ArrayList<>();
        for (int i = 0; i < v; i++) g.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt(), w = sc.nextInt();
            g.get(u).add(w);
        }
        System.out.println(zeroInDegreeCount(g));
    }

    static int zeroInDegreeCount(ArrayList<ArrayList<Integer>> g) {
        int[] indeg = new int[g.size()];
        for (ArrayList<Integer> nbrs : g) {
            for (int w : nbrs) indeg[w]++;
        }
        int count = 0;
        for (int i = 0; i < g.size(); i++) {
            if (indeg[i] == 0) count++;
        }
        return count;
    }
}

